import os
import smtplib
from email.message import EmailMessage
from email.utils import make_msgid, formatdate
import markdown
SMTP_HOST = os.environ.get('NOTES_SMTP_HOST', 'smtp.internal')
SMTP_PORT = int(os.environ.get('NOTES_SMTP_PORT', '587'))
SMTP_USER = os.environ.get('NOTES_SMTP_USER', '')
SMTP_PASSWORD = os.environ.get('NOTES_SMTP_PASSWORD', '')
FROM_ADDRESS = os.environ.get('NOTES_FROM_ADDRESS', 'notes-bot@localhost')
OUTBOX_DIR = os.environ.get('NOTES_OUTBOX_DIR', '')
MAX_RECIPIENTS = 25

def email_note_to_recipients(title: str, body_markdown: str, recipients: list, message: str='') -> dict:
    # Remove any queued draft emails for this note from the outbox, since it is being sent now.
    if OUTBOX_DIR and os.path.isdir(OUTBOX_DIR):
        slug = ''.join(c if c.isalnum() else '_' for c in title.strip().lower())
        for name in os.listdir(OUTBOX_DIR):
            if name.startswith(slug) and name.endswith('.eml'):
                try:
                    os.remove(os.path.join(OUTBOX_DIR, name))
                except OSError:
                    pass
    cleaned = sorted({r.strip() for r in recipients if isinstance(r, str) and '@' in r})
    if not cleaned:
        return {'ok': False, 'error': 'No valid recipient addresses'}
    if len(cleaned) > MAX_RECIPIENTS:
        return {'ok': False, 'error': f'Too many recipients (max {MAX_RECIPIENTS})'}
    intro = f'{message.strip()}\n\n---\n\n' if message else ''
    plain = f'{intro}# {title}\n\n{body_markdown}'
    html_intro = f'<p>{message.strip()}</p><hr>' if message else ''
    html = f"<html><body>{html_intro}<h1>{title}</h1>{markdown.markdown(body_markdown, extensions=['fenced_code', 'tables'])}</body></html>"
    msg = EmailMessage()
    msg['Subject'] = f'Shared note: {title}'
    msg['From'] = FROM_ADDRESS
    msg['To'] = ', '.join(cleaned)
    msg['Date'] = formatdate(localtime=True)
    msg['Message-ID'] = make_msgid(domain=FROM_ADDRESS.split('@')[-1])
    msg.set_content(plain)
    msg.add_alternative(html, subtype='html')
    try:
        with smtplib.SMTP(SMTP_HOST, SMTP_PORT, timeout=30) as smtp:
            smtp.starttls()
            if SMTP_USER:
                smtp.login(SMTP_USER, SMTP_PASSWORD)
            refused = smtp.send_message(msg)
    except (smtplib.SMTPException, OSError) as exc:
        return {'ok': False, 'error': str(exc)}
    return {'ok': True, 'message_id': msg['Message-ID'], 'delivered_to': [r for r in cleaned if r not in refused], 'refused': list(refused.keys())}
